{
  "probability": 0.01,
  "range_low": 0.01,
  "range_high": 0.03,
  "summary": [
    "Posterior probability: 1% for AfD to win the most seats.",
    "Late-February polls show AfD around 18–22% while CDU/Greens sit around 27–29%, making a lead unlikely.",
    "Historical base rate and Baden-Württemberg's mixed-member proportional system favor CDU/Greens, constraining AfD's seat potential.",
    "A small downside risk exists from turnout dynamics or late swings, but remains a tail event."
  ],
  "confidence": "low",
  "narrative": "Anchored on BW base rate, the late-February polling evidence reduces AfD’s odds of leading seats to a rare event. The Bayesian posterior yields about 1% probability, reflecting strong structural constraints and credible polling, with limited upside unless a late decisive shift occurs.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "reference class is Baden-Württemberg state elections where AfD has historically not won the most seats; anchor reflects base rate for the event within comparable elections."
    },
    "factor_updates": [
      {
        "factor": "Polling lead of CDU/Greens over AfD (Feb 2026 polls)",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Polls place AfD around 18–20% while CDU/Greens are in the upper 20s, reducing AfD's seat potential."
      },
      {
        "factor": "Historical base rate: AfD has never won the most seats in Baden-Württemberg",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Long-standing pattern creates a robust baseline constraint."
      },
      {
        "factor": "Electoral system (mixed-member proportional) amplifying large blocs",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "MMP tends to reward the largest blocs, limiting AfD's chances to lead in seats."
      },
      {
        "factor": "Two-party competition dynamic: CDU vs Greens",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Keeps AfD in third place in projections, reducing its scale of potential seat gains."
      },
      {
        "factor": "Upside risk: potential late swing or turnout shifts favoring AfD",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Unforeseen events or turnout shifts could temporarily raise AfD share, but current signals are weak."
      }
    ],
    "synthesis_rationale": "The posterior probability is derived by combining a modestly positive anchor with multiple independent downward updates from polls and structural constraints, while allowing a weak upward tail for turnout or late shifts. Given the correlation among polls and structural factors, the calibrated posterior lands at 1% with a narrow range, reflecting low confidence in a dramatic reversal absent major new evidence."
  }
}

